def render_area(a, site, page_hero, hours_table, ld_breadcrumb, ld_faq, faq_html):
    crumbs=[('홈','index.html'),(a['kw'], a['file'])]
    body = page_hero(dict(h1=a['h1'], lead=a['desc']), crumbs) + f'''
<section class="sec"><div class="wrap"><div class="grid g5-7" style="gap:56px;align-items:start">
  <div><h2 style="margin-bottom:16px">진료시간</h2>{hours_table()}<p style="margin-top:20px;font-family:var(--font-serif);font-size:19px;line-height:1.5">경기 시흥시 정왕대로 210<br>성담스퀘어 5층 518호</p><p class="small muted" style="margin-top:6px">전화 {site['phone_display']}</p></div>
  <div class="prose">{''.join(f'<p>{p}</p>' for p in a['intro'])}
    <h2>진료 안내</h2>
    <p>임플란트 · 풀아치 임플란트 · 네비게이션 임플란트 · 즉시로딩 · 틀니 · 의식하진정법 · 충치치료 · 신경치료 · 잇몸치료 · 사랑니 발치 · 스케일링 · 레진 · 인레이 · 크라운 · 보철 · 치아미백 · 라미네이트 · 턱관절 치료</p>
    <div class="related"><a href="implant.html">임플란트</a><a href="sedation.html">의식하진정법</a><a href="cavity.html">충치치료</a><a href="rootcanal.html">신경치료</a><a href="gum.html">잇몸치료</a><a href="doctors.html">의료진</a><a href="location.html">오시는 길</a></div>
    <h2>증상으로 찾기</h2>
    <div class="related">{''.join(f'<a href="{s["file"]}">{esc(s["h1"])}</a>' for s in SYMPTOM)}</div>
  </div>
</div></div></section>''' + faq_html(a['faq'], f'{esc(a["kw"])} 자주 묻는 질문')
    page = dict(file=a['file'], title=a['title'], description=a['desc'], ai_summary=a['desc'], h1=a['h1'])
    return dict(page=page, body=body, ld=[ld_breadcrumb(crumbs), ld_faq(a['faq'])], prio='0.8')

def render_symptom(s, site, page_hero, ld_breadcrumb, ld_faq, faq_html, ld_medpage, doctor_names):
    crumbs=[('홈','index.html'),('증상으로 찾기','symptoms.html'),(s['h1'], s['file'])]
    body = page_hero(dict(h1=s['h1'], lead=s['q']), crumbs) + f'''
<section class="sec"><div class="wrap prose">
  <p class="tx-summary" style="font-size:18px">{s['desc'].split('. 시흥')[0]}.</p>
  <h2>생각해 볼 수 있는 원인</h2><ul>{''.join(f'<li>{c}</li>' for c in s['causes'])}</ul>
  <h2>치과에서 확인하는 것</h2><p>{s['check']}</p>
  <h2>관련 치료 안내</h2><div class="related">{''.join(f'<a href="{h}">{l}</a>' for l,h in s['links'])}</div>
  <p class="small muted" style="margin-top:24px">여기 적힌 내용은 일반적인 설명이며 진단을 대신하지 않습니다. 증상이 계속되면 검사를 받으시고, 치료 방법과 결과는 개인의 상태에 따라 다릅니다.</p>
  <div class="tx-meta"><span>작성 {esc(site['name'])}</span><span>검토 {doctor_names[s['reviewer']]}</span></div>
</div></section>''' + faq_html(s['faq'])
    page = dict(file=s['file'], title=s['title'], description=s['desc'], ai_summary=s['desc'], h1=s['h1'])
    return dict(page=page, body=body, ld=[ld_breadcrumb(crumbs), ld_medpage(page, s['reviewer']), ld_faq([(s['q'], s['check'])]+s['faq'])], prio='0.7')

def render_symptom_index(site, page_hero, ld_breadcrumb):
    crumbs=[('홈','index.html'),('증상으로 찾기','symptoms.html')]
    items=''.join(f'<a href="{s["file"]}" class="card" style="padding:20px 22px;text-decoration:none;display:block"><span style="font-family:var(--font-serif);font-weight:600;font-size:19px;display:block">{esc(s["h1"])}</span><span class="small muted" style="display:block;margin-top:6px">{esc(s["q"])}</span></a>' for s in SYMPTOM)
    page=dict(file='symptoms.html', h1='증상으로 찾기', title='증상으로 찾기 — 이가 시려요, 잇몸에서 피가 나요, 치아가 흔들려요 | 바로드림치과의원 시화점',
              description='증상별로 가능한 원인과 치과에서 확인하는 것을 설명합니다. 이가 시려요, 잇몸 출혈, 흔들리는 치아, 씹을 때 통증, 턱 소리, 치과 공포, 빠진 치아, 사랑니 통증.', lead='치료 이름을 몰라도 괜찮습니다. 지금 느끼시는 증상으로 찾아보세요.')
    body = page_hero(page, crumbs) + f'<section class="sec"><div class="wrap"><div class="grid g2" style="gap:16px;max-width:900px">{items}</div></div></section>'
    return dict(page=page, body=body, ld=[ld_breadcrumb(crumbs)], prio='0.7')
